  sentOk: { es:"✅ Gracias. Tu aviso ya está con la oficina y el equipo pastoral; te contactarán pronto.", en:"✅ Thank you. Your request is now with the office and the pastoral team; they will contact you soon.", pt:"✅ Obrigado. Seu aviso já está com a secretaria e a equipe pastoral; entrarão em contato em breve.", it:"✅ Grazie. Il tuo avviso è già all'ufficio e all'équipe pastorale; ti contatteranno presto.", la:"✅ Gratias. Monitio tua iam ad officium et turmam pastoralem pervenit; te mox convenient.", fr:"✅ Merci. Votre demande est bien arrivée au bureau et à l'équipe pastorale ; on vous contactera bientôt.", zh:"✅ 谢谢。您的请求已送达办公室和牧灵团队，他们会尽快联系您。", tl:"✅ Salamat. Nasa opisina at pastoral team na ang kahilingan mo; kokontakin ka nila.", vi:"✅ Cảm ơn. Yêu cầu của bạn đã đến văn phòng và nhóm mục vụ; họ sẽ liên lạc sớm.", ar:"✅ شكرًا. طلبك وصل إلى المكتب والفريق الرعوي؛ سيتواصلون معك قريبًا.", ko:"✅ 감사합니다. 사무실과 사목팀에 전달되었습니다. 곧 연락드리겠습니다." },
  teamT: { es:"Equipo pastoral: avisos recibidos", en:"Pastoral team: requests received", pt:"Equipe pastoral: avisos recebidos", it:"Équipe pastorale: avvisi ricevuti", la:"Turma pastoralis: monitiones acceptae", fr:"Équipe pastorale : demandes reçues", zh:"牧灵团队：收到的请求", tl:"Pastoral team: natanggap na kahilingan", vi:"Nhóm mục vụ: yêu cầu đã nhận", ar:"الفريق الرعوي: الطلبات المستلمة", ko:"사목팀: 접수된 요청" },
  pubPetition: { es:"Hacerla pública en Intenciones (la revisa el párroco antes de publicar)", en:"Make it public in Intentions (the pastor reviews it before posting)", pt:"Torná-la pública nas Intenções (o pároco revê antes de publicar)", it:"Rendi pubblica nelle Intenzioni (il parroco la rivede prima di pubblicare)", la:"Publica in Intentionibus (parochus antea recognoscet)", fr:"Rendre publique dans les Intentions (le curé vérifie avant publication)", zh:"公开发布到代祷意向（本堂神父先审核）", tl:"Gawing pampubliko sa mga Intensyon (rerepasuhin muna ng kura)", vi:"Công khai trong Các ý chỉ (cha xứ duyệt trước khi đăng)", ar:"اجعلها علنية في النيات (الكاهن يراجعها قبل النشر)", ko:"지향에 공개 게시 (신부님이 먼저 검토합니다)" },
  pendingReview: { es:"⏳ Tu petición quedó en revisión. El párroco la publicará en Intenciones si es apropiada.", en:"⏳ Your petition is under review. The pastor will post it in Intentions if appropriate.", pt:"⏳ Seu pedido está em revisão. O pároco o publicará nas Intenções se for apropriado.", it:"⏳ La tua richiesta è in revisione. Il parroco la pubblicherà nelle Intenzioni se appropriata.", la:"⏳ Petitio tua recognoscitur. Parochus eam in Intentionibus publicabit si convenit.", fr:"⏳ Votre demande est en cours de vérification. Le curé la publiera dans les Intentions si elle convient.", zh:"⏳ 您的请求正在审核中。如合适本堂神父将发布到代祷意向。", tl:"⏳ Nasa pagsusuri ang kahilingan mo. Ipo-post ito ng kura sa mga Intensyon kung nararapat.", vi:"⏳ Lời xin của bạn đang được duyệt. Cha xứ sẽ đăng trong Các ý chỉ nếu phù hợp.", ar:"⏳ طلبك قيد المراجعة. سينشره الكاهن في النيات إذا كان مناسبًا.", ko:"⏳ 청원이 검토 중입니다. 적절하면 신부님이 지향에 게시합니다." },
  reviewBadge: { es:"⏳ En revisión (petición pública)", en:"⏳ Under review (public petition)", pt:"⏳ Em revisão (pedido público)", it:"⏳ In revisione (richiesta pubblica)", la:"⏳ Recognoscenda (petitio publica)", fr:"⏳ En vérification (demande publique)", zh:"⏳ 审核中（公开请求）", tl:"⏳ Sinusuri (pampublikong kahilingan)", vi:"⏳ Đang duyệt (lời xin công khai)", ar:"⏳ قيد المراجعة (طلب علني)", ko:"⏳ 검토 중 (공개 청원)" },
