  gateNoUser: { es:"No hay cuenta con ese nombre. Usa tu invitación o pide ayuda en la oficina.", en:"No account with that name. Use your invitation or ask the office.", pt:"Não há conta com esse nome. Usa o teu convite ou pede ajuda na secretaria.", it:"Non c'è un account con questo nome. Usa il tuo invito o chiedi aiuto in ufficio.", la:"Nulla ratio hoc nomine est. Invitatione tua utere aut auxilium ab officio pete.", fr:"Aucun compte à ce nom. Utilise ton invitation ou demande de l'aide au bureau.", zh:"没有此姓名的账户。请使用邀请码或到办公室求助。", tl:"Walang account sa pangalang iyan. Gamitin ang iyong imbitasyon o humingi ng tulong sa opisina.", vi:"Không có tài khoản tên này. Hãy dùng thư mời hoặc hỏi văn phòng.", ar:"لا يوجد حساب بهذا الاسم. استخدم دعوتك أو اطلب المساعدة من المكتب.", ko:"그 이름의 계정이 없습니다. 초대 코드를 사용하거나 사무실에 문의하세요." },
  gateWaitNet: { es:"Necesitas internet la primera vez. Conéctate e inténtalo de nuevo.", en:"You need internet the first time. Connect and try again.", pt:"Precisas de internet na primeira vez. Liga-te e tenta de novo.", it:"Serve internet la prima volta. Connettiti e riprova.", la:"Prima vice interrete opus est. Conecte et itera.", fr:"Il faut internet la première fois. Connecte-toi et réessaie.", zh:"首次需要联网。请连接后重试。", tl:"Kailangan ng internet sa unang pagkakataon. Kumonekta at subukang muli.", vi:"Lần đầu cần có mạng. Hãy kết nối rồi thử lại.", ar:"تحتاج إلى الإنترنت في المرة الأولى. اتصل ثم حاول مجددًا.", ko:"처음에는 인터넷이 필요합니다. 연결 후 다시 시도하세요." },
  pwShort: { es:"La contraseña debe tener al menos 6 caracteres.", en:"Password must be at least 6 characters.", pt:"A senha deve ter pelo menos 6 caracteres.", it:"La password deve avere almeno 6 caratteri.", la:"Tessera sex notas saltem habeat.", fr:"Le mot de passe doit avoir au moins 6 caractères.", zh:"密码至少需要6个字符。", tl:"Ang password ay dapat may hindi bababa sa 6 na karakter.", vi:"Mật khẩu phải có ít nhất 6 ký tự.", ar:"يجب أن تتكون كلمة المرور من 6 أحرف على الأقل.", ko:"비밀번호는 최소 6자 이상이어야 합니다." },
