  pwNewL: { es:"Nueva contraseña (mín. 6)", en:"New password (min. 6)", pt:"Nova senha (mín. 6)", it:"Nuova password (min. 6)", la:"Nova tessera (min. 6)", fr:"Nouveau mot de passe (min. 6)", zh:"新密码（至少6位）", tl:"Bagong password (min. 6)", vi:"Mật khẩu mới (tối thiểu 6)", ar:"كلمة مرور جديدة (6 على الأقل)", ko:"새 비밀번호 (최소 6자)" },
  pwChangeBtn: { es:"Guardar contraseña", en:"Save password", pt:"Guardar senha", it:"Salva password", la:"Tesseram serva", fr:"Enregistrer le mot de passe", zh:"保存密码", tl:"I-save ang password", vi:"Lưu mật khẩu", ar:"حفظ كلمة المرور", ko:"비밀번호 저장" },
